pub use __cargo_equip::prelude::*;

use crate::__cargo_equip::crates::{
    input::*, montodd::*, obuf::*, rho::factorize, xorshift::Xorshift64,
};

pub fn solve<I: NextToken>(input: &mut I) {
    // Initialize.
    #[rustfmt::skip] #[cfg(tcheck)] let tins = std::time::Instant::now();
    #[rustfmt::skip] #[cfg(tcheck)] let mut durs = Vec::with_capacity(16);
    #[rustfmt::skip] #[allow(unused_macros)] macro_rules! input {($($r:tt)*)=>{input_inner!{input,$($r)*}};}
    #[rustfmt::skip] #[allow(unused_macros)] macro_rules! read {($t:tt)=>{{read_value!(input,$t)}};}
    let mut obuf = ProconWriteBuffer::with_capacity(1 << 26);
    let mut out = std::io::stdout();

    input! { q: usize }
    let mut rng = Xorshift64::new();
    for _ in 0..q {
        input! { p: u64 }
        if p == 2 {
            obuf.uint(1u32);
            obuf.lf();
            continue;
        }
        let mut p1f = factorize(p - 1);
        p1f.dedup();
        let mont = Mont::<u64>::new(p);
        'rloop: /* ' */ loop {
            let r = (((rng.next_u64() as u128) * ((p - 2) as u128)) >> 64) as u64 + 2;
            let rr = mont.ar(r);
            for &f in p1f.iter() {
                if mont.pow(rr, (p - 1) / f) == mont.r() {
                    continue 'rloop; /* ' */
                }
            }
            obuf.uint(r);
            obuf.lf();
            break;
        }
    }

    #[rustfmt::skip] #[cfg(tcheck)] durs.push((tins.elapsed(), "solve"));
    obuf.write_all(&mut out);
    #[rustfmt::skip] #[cfg(tcheck)] durs.push((tins.elapsed(), "output"));

    // Execution Time.
    #[rustfmt::skip] #[cfg(tcheck)] for (dur, s) in durs.iter() { eprintln!("{:.6} {}", dur.as_secs_f64(), s); };
}

#[cfg(not(target_os = "linux"))]
fn launch() {
    let stdin = std::io::stdin();
    solve(&mut fastproconio::ProconIBufIter::new(stdin.lock()));
}
#[cfg(target_os = "linux")]
fn launch() {
    unsafe {
        use std::os::unix::io::FromRawFd;
        match std::fs::File::from_raw_fd(0).metadata() {
            Ok(metadata) if metadata.is_file() => {
                let filelen = metadata.len();
                let input = mmap(std::ptr::null_mut(), filelen as usize, 1, 2, 0, 0);
                solve(&mut BytesIter(std::slice::from_raw_parts(
                    input,
                    filelen as usize,
                )));
            }
            _ => {
                let stdin = std::io::stdin();
                solve(&mut ProconIBufIter::new(stdin.lock()));
            }
        }
    }
}

fn main() {
    const USE_THREAD: bool = false;
    if USE_THREAD {
        // In order to avoid potential stack overflow, spawn a new thread.
        let stack_size = 134_217_728; // 128 MB
        let thd = std::thread::Builder::new().stack_size(stack_size);
        thd.spawn(|| launch()).unwrap().join().unwrap();
    } else {
        launch()
    }
}

